	@Test
	void messageType() {
		// Assert: each constant's exact surface (values and renderings from the schema)
		assertThat(MessageType.PLAIN.getValue(), equalTo(1L));
		assertThat(MessageType.PLAIN.toString(), equalTo("MessageType.PLAIN"));
		assertThat(MessageType.PLAIN.toJson(), equalTo(1L));
		assertThat(MessageType.PLAIN.serialize(), equalTo(new byte[]{
				(byte) 0x01, (byte) 0x00, (byte) 0x00, (byte) 0x00
		}));
		assertThat(MessageType.ENCRYPTED.getValue(), equalTo(2L));
		assertThat(MessageType.ENCRYPTED.toString(), equalTo("MessageType.ENCRYPTED"));
		assertThat(MessageType.ENCRYPTED.toJson(), equalTo(2L));
		assertThat(MessageType.ENCRYPTED.serialize(), equalTo(new byte[]{
				(byte) 0x02, (byte) 0x00, (byte) 0x00, (byte) 0x00
		}));

		// Act + Assert: every constant round-trips through each generated parse arm
		for (final MessageType constant : MessageType.values()) {
			assertThat(constant.size(), equalTo(4));
			assertThat(MessageType.parse(constant), sameInstance(constant));
			assertThat(MessageType.parse(constant.name().toLowerCase(Locale.ROOT)), sameInstance(constant));
			assertThat(MessageType.parse(constant.getValue()), sameInstance(constant));
		}
	}

